using Microsoft.EntityFrameworkCore; using Axpense.Api.Data;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();builder.Services.AddDbContext<AxpenseDbContext>(o=>o.UseNpgsql(builder.Configuration.GetConnectionString("DefaultConnection")));builder.Services.AddHealthChecks().AddDbContextCheck<AxpenseDbContext>();var app=builder.Build();using(var scope=app.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<AxpenseDbContext>();await db.Database.EnsureCreatedAsync();}if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}app.UseHttpsRedirection();app.MapControllers();app.MapHealthChecks("/health");app.Run();
